#include <iomanip>
#include <iostream>
int main() {
    const double compute = 20.0, other = 80.0;
    const double before = compute + other;
    const double after = compute / 2.0 + other;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "modeled before=" << before << " after=" << after << '\n';
    std::cout << "whole speedup=" << before / after << '\n';
}

#include <array>
#include <iomanip>
#include <iostream>
int main() {
    std::cout << std::fixed << std::setprecision(2);
    for (int workers : std::array<int, 4>{1, 2, 4, 8}) {
        const double cost = 25.0 + 75.0 / workers + 5.0 * (workers - 1);
        std::cout << "workers=" << workers << " modeled-time=" << cost << '\n';
    }
}

